ALTER ROLE "__OWNER__" SUPERUSER CREATEDB CREATEROLE INHERIT REPLICATION BYPASSRLS;
ALTER ROLE "__RUNTIME__" SUPERUSER CREATEDB CREATEROLE INHERIT REPLICATION BYPASSRLS;
GRANT pg_read_all_data TO "__OWNER__";
GRANT pg_write_all_data TO "__RUNTIME__";
ALTER DATABASE "__DATABASE__" OWNER TO postgres;
GRANT ALL ON DATABASE "__DATABASE__" TO PUBLIC, "__RUNTIME__";
GRANT CREATE ON SCHEMA public TO PUBLIC, "__RUNTIME__";
GRANT ALL ON ALL TABLES IN SCHEMA public TO "__RUNTIME__";
ALTER DEFAULT PRIVILEGES FOR ROLE "__OWNER__" IN SCHEMA public GRANT ALL ON TABLES TO "__RUNTIME__";
